// Friendly names for the generated API types. `schema.ts` is generated by `make contracts`;
// never edit it by hand. Add an alias here when the app needs a new type.
import type { components, paths } from "./schema";

export type { components, paths };

type Schemas = components["schemas"];

/** POST /illustrate body: a word, a short phrase, or one sentence. */
export type IllustrateRequest = Schemas["IllustrateRequest"];
/** POST /illustrate response. Fetch `url` (relative to the API base) for the image bytes. */
export type IllustrateResponse = Schemas["IllustrateResponse"];
